import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import Avatar from 'flarum/common/components/Avatar';
import humanTime from 'flarum/common/utils/humanTime';
import CommentPost from 'flarum/forum/components/CommentPost';

/**
 * Telefon akış kartı (Instagram düzeni): Flarum mesaj bileşeni yerine kendi kartımız.
 * Üst satır avatar · ad · zaman, kenardan kenara fotoğraflar (birden çoksa yana kaydırma),
 * etkileşim simgeleri, beğeni sayısı, başlık + künye ve yorumlara bağlantı.
 */
export default class MobileFeedCard extends Component {
  oninit(vnode) {
    super.oninit(vnode);
    this.index = 0;
    this.parse();
  }

  // Mesaj içeriğinden fotoğrafları ve künye satırlarını ayıklar
  parse() {
    const post = this.attrs.post;
    const box = document.createElement('div');
    box.innerHTML = post.contentHtml() || '';
    this.images = [...box.querySelectorAll('img')].filter(i => !i.classList.contains('emoji') && !/avatar|emoji/i.test(i.className)).map(i => {
      const box2 = i.closest('[data-id]');
      return {
        src: i.getAttribute('src') || i.getAttribute('data-src'),
        alt: i.getAttribute('alt') || '',
        w: i.getAttribute('width'),
        h: i.getAttribute('height'),
        id: box2 ? box2.getAttribute('data-id') : null
      };
    }).filter(i => i.src);
    // Künye: masaüstündeki kartın kendi HTML'i aynen kullanılır (tasarım kimliği korunur)
    const kunye = box.querySelector('.framio-kunye-card') || box.querySelector('ul');
    this.kunyeHtml = kunye ? kunye.outerHTML : '';
    this.facts = [...box.querySelectorAll('ul li')].map(li => li.textContent.trim()).filter(Boolean).slice(0, 4);
    box.querySelectorAll('ul, img, script, style').forEach(n => n.remove());
    this.caption = box.textContent.replace(/\s+/g, ' ').trim().slice(0, 160);
  }
  view() {
    const post = this.attrs.post;
    const user = post.user();
    const discussion = post.discussion();
    const url = app.route.post(post);
    const likes = post.likes ? post.likes() || [] : [];
    const likesCount = post.likesCount && post.likesCount() || likes.length;
    const me = app.session.user;
    const isLiked = !!(me && likes.some(u => u === me));
    const replies = discussion ? Math.max(0, (discussion.commentCount() || 1) - 1) : 0;
    const multi = this.images.length > 1;
    return m("article", {
      className: "FeedCard"
    }, m("header", {
      className: "FeedCard-head"
    }, user ? m(Link, {
      href: app.route.user(user),
      className: "FeedCard-user"
    }, m(Avatar, {
      user: user
    }), m("b", null, user.displayName())) : null, m("span", {
      className: "FeedCard-time"
    }, "\xB7 ", humanTime(post.createdAt()))), this.images.length ? m("div", {
      className: "FeedCard-media"
    }, m("div", {
      className: "FeedCard-track Post-body",
      onscroll: e => {
        const n = Math.round(e.target.scrollLeft / e.target.clientWidth);
        if (n !== this.index) {
          this.index = n;
          m.redraw();
        }
      }
    }, this.images.map(img => m("div", {
      className: "FeedCard-slide"
    }, m("img", {
      src: img.src,
      alt: img.alt,
      loading: "lazy",
      decoding: "async",
      width: img.w,
      height: img.h
    })))), multi ? m("span", {
      className: "FeedCard-count"
    }, this.index + 1, "/", this.images.length) : null) : null, this.exifCard(), m("div", {
      className: "FeedCard-actions"
    }, m("button", {
      type: "button",
      className: 'FeedCard-act' + (isLiked ? ' liked' : ''),
      "aria-label": "Be\u011Fen",
      onclick: () => this.toggleLike(isLiked),
      disabled: post.canLike && post.canLike() === false
    }, m("i", {
      className: (isLiked ? 'fas' : 'far') + ' fa-heart'
    })), m(Link, {
      className: "FeedCard-act",
      href: url,
      "aria-label": "Yorumlar"
    }, m("i", {
      className: "far fa-comment"
    })), m("button", {
      type: "button",
      className: "FeedCard-act",
      "aria-label": "Payla\u015F",
      onclick: () => this.share(url)
    }, m("i", {
      className: "far fa-paper-plane"
    })), multi ? m("span", {
      className: "FeedCard-dots"
    }, this.images.map((_, k) => m("i", {
      className: k === this.index ? 'on' : ''
    }))) : null), likesCount ? m("div", {
      className: "FeedCard-likes"
    }, likesCount, " be\u011Feni") : null, m("div", {
      className: "FeedCard-text"
    }, discussion ? m(Link, {
      href: url,
      className: "FeedCard-title"
    }, discussion.title()) : null, !this.kunyeHtml && this.caption ? m("p", null, this.caption) : null), this.kunyeHtml ? m("div", {
      className: "FeedCard-kunye Post-body"
    }, m.trust(this.kunyeHtml)) : null, m("div", {
      className: "FeedCard-text"
    }, replies ? m(Link, {
      href: url,
      className: "FeedCard-more"
    }, replies, " yorumun t\xFCm\xFCn\xFC g\xF6r") : null));
  }

  // Açık fotoğrafın EXIF kartı: Upload & EXIF eklentisinin kendi bileşeni (mesaj sayfasındakiyle aynı)
  exifCard() {
    const img = this.images[this.index];
    const Card = window.FramioImageManager && window.FramioImageManager.SpotterImageCard;
    if (!img || !img.id || !Card) return null;
    // Anahtar yalnızca iç bileşende: kart içindeki diğer elemanlar anahtarsız olduğundan dış kutu anahtarsız kalmalı
    // Masaüstündeki sarmalayıcılarla aynı yapı: kartın kendi stilleri bu sınıflara bağlı
    return m("div", {
      className: "FeedCard-exif Post-body"
    }, m("div", {
      className: "framio-image-container SpotterCard"
    }, m("div", {
      className: "spotter-exif-placeholder"
    }, [m(Card, {
      key: 'exif-' + img.id,
      photoId: img.id,
      post: this.attrs.post
    })])));
  }
  toggleLike(isLiked) {
    const post = this.attrs.post;
    if (!app.session.user) {
      flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal').then(mod => app.modal.show(mod.default));
      return;
    }
    const me = app.session.user;
    const likes = (post.likes && post.likes() || []).filter(u => u !== me);
    if (!isLiked) likes.unshift(me);
    post.pushData({
      relationships: {
        likes
      }
    });
    if (post.likesCount) post.pushAttributes({
      likesCount: (post.likesCount() || 0) + (isLiked ? -1 : 1)
    });
    post.save({
      isLiked: !isLiked
    });
  }

  // Paylaşım menüsü (alttan açılan sayfa): bağlantı paylaşımı + eklentilerin mesaja eklediği işlemler
  // (Sosyal Medyada Paylaş, ağa aktar vb.) — Flarum mesaj bileşeninin işlem listesinden alınır.
  share(url) {
    let items = [];
    try {
      const cp = new CommentPost();
      cp.attrs = {
        post: this.attrs.post
      };
      items = cp.actionItems().toArray().filter(v => v && !['like', 'reply'].includes(v.itemName));
    } catch (e) {}
    const host = document.createElement('div');
    host.className = 'FeedSheet';
    const close = () => {
      m.mount(host, null);
      host.remove();
    };
    document.body.appendChild(host);
    m.mount(host, {
      view: () => m("div", {
        className: "FeedSheet-backdrop",
        onclick: e => {
          if (e.target === e.currentTarget) close();
        }
      }, m("div", {
        className: "FeedSheet-panel",
        onclick: e => {
          if (e.target.closest('button, a') && !e.target.closest('.FeedSheet-link')) setTimeout(close, 0);
        }
      }, m("span", {
        className: "FeedSheet-grip"
      }), m("button", {
        type: "button",
        className: "FeedSheet-link Button",
        onclick: () => {
          this.nativeShare(url);
          close();
        }
      }, m("i", {
        className: "icon fas fa-link"
      }), " Ba\u011Flant\u0131y\u0131 payla\u015F"), items))
    });
  }
  nativeShare(url) {
    const full = app.forum.attribute('baseUrl') + url.replace(app.forum.attribute('basePath') || '', '');
    const title = this.attrs.post.discussion() ? this.attrs.post.discussion().title() : document.title;
    if (navigator.share) navigator.share({
      title,
      url: full
    }).catch(() => {});else if (navigator.clipboard) navigator.clipboard.writeText(full).then(() => app.alerts.show({
      type: 'success'
    }, 'Bağlantı kopyalandı'));
  }
}
flarum.reg.add('framio-custom-homepage', 'forum/components/MobileFeedCard', MobileFeedCard);